import React, { useEffect, useState } from 'react';

function LifetimeWithdraw() {
  const [lifetimeWinning, setLifetimeWinning] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // এখানে টোকেন রাখো, সাধারণত এটা localStorage বা context থেকে নেওয়া হয়
  const token = "eyJhbGciOiJIUzI1NiJ9.eyJzdWIiOiIzODc2NDI0NjY1ODUiLCJpYXQiOjE3NTQ2NjI1NjMsImV4cCI6MTc1NDc0ODk2M30.ra6GKbrOfn-dK3-unvRmSmUJyUXu5UrE0NKhNt8SZVY";

  useEffect(() => {
    fetch('/api/withdraw/lifetime', {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`,  // টোকেন যোগ করলাম
      },
    })
      .then(async (res) => {
        if (!res.ok) {
          const errorText = await res.text();
          throw new Error(errorText || 'লাইফটাইম উইনিং ফেচ করতে সমস্যা হয়েছে');
        }
        return res.json();
      })
      .then(data => {
        if (data && typeof data.total === 'number') {
          setLifetimeWinning(data.total);
        } else {
          throw new Error('অপ্রত্যাশিত ডাটা ফরম্যাট');
        }
        setLoading(false);
      })
      .catch(err => {
        setError(err.message);
        setLoading(false);
      });
  }, [token]); // টোকেন ডিপেনডেন্সি দিলাম

  if (loading) return <div>লোড হচ্ছে...</div>;
  if (error) return <div>ত্রুটি: {error}</div>;

  return (
    <div>
      <h2>লাইফটাইম উইনিং</h2>
      <p>৳ {lifetimeWinning.toFixed(2)}</p>
    </div>
  );
}

export default LifetimeWithdraw;
